export type Author = {
    label: string;
    value: string;
};
export type GetAuthors = (params?: {
    page?: number;
}) => void;
export type GetAuthorsResponse = {
    authors: Author[];
    meta: {
        pagination: {
            authors: {
                perPage: number;
                total: number;
            };
            pages: {
                current: number;
                total: number;
            };
        };
    };
};
export type UseGetAuthors = () => {
    getAuthors: GetAuthors;
    authors: Author[];
    isLoading: boolean;
};
